n = 25
min_degree = 3
max_degree = 5

def get_edges_from_adj(adj):
    edges = []
    for i in range(n):
        for j in adj[i]:
            if i < j:
                edges.append((i, j))
    return edges

def has_cycle_of_length(adj, length):
    """Check if there's a cycle of given length"""
    # BFS from each vertex to find cycles
    for start in range(n):
        # BFS with path tracking
        visited = {start: [start]}
        queue = [start]
        for _ in range(length - 1):
            new_queue = []
            for v in queue:
                for neighbor in adj[v]:
                    if neighbor == start and len(visited[v]) == length:
                        return True
                    if neighbor not in visited:
                        visited[neighbor] = visited[v] + [neighbor]
                        new_queue.append(neighbor)
            queue = new_queue
    return False

def check_girth(adj, max_cycle=6):
    """Check that girth is at least max_cycle+1"""
    for length in range(3, max_cycle + 1):
        if has_cycle_of_length(adj, length):
            return False
    return True

def get_degree(adj, v):
    return len(adj[v])

