import random
from collections import deque

n = 25
min_degree = 3
max_degree = 5

def would_create_short_cycle(adj, u, v, max_cycle_len=6):
    """Check if adding edge (u,v) would create a cycle of length <= max_cycle_len"""
    # BFS from u to v in the current graph (without the edge u-v)
    # If there's a path of length <= max_cycle_len - 1, adding (u,v) creates a short cycle
    dist = {u: 0}
    queue = deque([u])
    while queue:
        curr = queue.popleft()
        if dist[curr] >= max_cycle_len:
            continue
        for neighbor in adj[curr]:
            if neighbor not in dist:
                dist[neighbor] = dist[curr] + 1
                if neighbor == v:
                    # Path of length dist[neighbor] from u to v
                    # Adding edge (u,v) creates cycle of length dist[neighbor] + 1
                    return True
                queue.append(neighbor)
    return False

def try_construct_with_backtracking():
    random.seed(123)
    adj = [set() for _ in range(n)]

    # Try multiple random orderings
    for attempt in range(100):
        random.seed(attempt * 1000)
        adj = [set() for _ in range(n)]

        all_possible = [(i, j) for i in range(n) for j in range(i+1, n)]
        random.shuffle(all_possible)

        for i, j in all_possible:
            if len(adj[i]) >= max_degree or len(adj[j]) >= max_degree:
                continue

            if not would_create_short_cycle(adj, i, j, 6):
                adj[i].add(j)
                adj[j].add(i)

        degrees = [len(adj[v]) for v in range(n)]
        if min(degrees) >= 3:
            print(f"Attempt {attempt}: Success!")
            print("Degrees:", degrees)
            edges = []
            for i in range(n):
                for j in adj[i]:
                    if i < j:
                        edges.append((i, j))
            return edges

    return None

result = try_construct_with_backtracking()
if result:
    print("Found solution!")
    print(result)
else:
